-- Apply after 202610170009_loki_card.sql.
-- Full character engine. Choices are validated and resolved on the server.
begin;
alter table public.card_lore drop constraint if exists card_lore_card_id_check;
alter table public.card_lore add constraint card_lore_card_id_check check(card_id in ('soldado-esparta','athena','lobo-alfa','guardiao-nordico','mjolnir','runas-nordicas','grecia','eclipse','campo-troia','medusa','poseidon','zeus','hades','lobo-omega','lukyan','anubis','odin','lukyan-rei-de-todos','minotauro','apolo','ra','ragnar','afrodite','aquiles','seth','osiris','thor','artemis','sobek','ares','beowulf','heimdall','dionisio','butter','hefesto','hercules','hermes','horus','lobo-beta','isis','mulher','homem','yggdrasil','alto-egito','baixo-egito','bifrost','esparta','labirinto-dedalos','nilfheim','asgard','egito','olho-que-tudo-ve','raio-de-zeus','excalibur','eclipse-lunar','eclipse-solar','loki'));
insert into public.card_lore(card_id,card_name,ability_title,ability_text,art_url,faction,power,badge_key) values
('athena','Athena','Formação Falange','Todas as outras cartas na mesma fileira de Athena ganham +2 pontos de poder cada.','assets/cards-20261017/athena.png','Grécia',4,'greece'),
('lobo-alfa','Lobisomem Alfa','Uivo de Alfa','A cada Lobisomem Beta em campo, ganha 2 pontos de poder.','assets/cards-20261017/lobo-alfa.png','Monstros',4,'monster'),
('mjolnir','Mjölnir','Equipar','Somente Thor pode equipar. Concede +4 de poder.','assets/equipment/mjolnir.png','Nórdicos',0,'norse'),
('runas-nordicas','Runa Uruz','Equipar','Um personagem nórdico à sua escolha recebe +2 de poder.','assets/equipment/runas-nordicas.png','Nórdicos',0,'norse'),
('grecia','Grécia','Bônus de Local','Enquanto este Local estiver ativo, todos os gregos recebem +2 de poder, nos dois lados do campo.','assets/locations/grecia.png','Grécia',0,'greece'),
('eclipse','Eclipse','Destino Celestial','Ao jogar na área de Clima/Evento, sorteia Eclipse Lunar ou Solar, com 50% de chance para cada. O resultado afeta os dois lados até o fim da rodada.','assets/eclipse/eclipse.png','Universal',0,null),
('campo-troia','Troia','Bônus de Terreno','Fortalece Aquiles, Athena e Ares em +3 de poder.','assets/terrains/campo-troia.png','Grécia',0,'greece'),
('hades','Hades','Submundo Responda','Ao entrar em campo, escolha uma carta do seu próprio Submundo para voltar ao campo. A carta retorna na fileira de Hades e ativa sua habilidade de entrada.',null,'Grécia',7,null),
('lobo-omega','Lobisomem Omega','Encurralado','Se o Lobisomem Omega for o único na sua fileira de batalha e o inimigo tiver mais poder que o Omega, seu poder aumenta em 8.','assets/cards-20261017/lobo-omega.png','Monstros',1,'monster'),
('lukyan','Lukyan — Rei da Festa','Rei da Festa','Ao entrar numa fileira com outros personagens, ganha +3 pontos de poder.','assets/cards-20261017/lukyan.png','Alyns',3,'alyans'),
('anubis','Anúbis','Troca Veloz','Ao entrar em campo, escolhe uma carta inimiga com 3 ou menos pontos de poder e a envia para o Submundo. Recupera uma carta de mesmo poder do Submundo do invocador.','assets/cards-20261017/anubis.png','Egípcios',5,'egypt'),
('odin','Odin','Sabedoria de Yggdrasil','No início do próximo turno do dono, observe a carta do topo do seu baralho. Você pode descartá-la para ganhar +2 na soma da rodada ou mantê-la no topo.','assets/cards-20261017/odin.png','Nórdicos',8,'norse'),
('lukyan-rei-de-todos','Lukyan — Rei de Todos','Rei de Todos','Agora com Excalibur, Lukyan tem seu poder dobrado por todos seus aliados em campo. Só aparece pela transformação de Lukyan com Excalibur; não pode entrar no baralho ou na mão.','assets/cards-20261017/lukyan-rei-de-todos.png','Alyns',6,'alyans'),
('minotauro','Minotauro','Fúria do Labirinto','Ao entrar em campo, se estiver sozinho em sua fileira de batalha, ganha +3 pontos de poder.','assets/cards-20261017/minotauro.png','Grécia',3,'greece'),
('apolo','Apolo','Benção do Sol','Ao ser colocado numa fileira, todos os personagens dessa fileira têm seu poder dobrado.','assets/cards-20261017/apolo.png','Grécia',6,'greece'),
('ra','Rá','Luz da Criação','No final de cada rodada, adiciona +1 de poder a todas as cartas da sua facção Egito em campo.','assets/cards-20261017/ra.png','Egípcios',8,'egypt'),
('ragnar','Ragnar','Invasores de Katgat','Ao entrar em campo, move uma carta aliada de baixo poder de outra fileira para a mesma fileira de Ragnar, unindo as forças.','assets/cards-20261017/ragnar.png','Nórdicos',3,'norse'),
('afrodite','Afrodite','Meu Amado Traidor','Ao entrar em campo, o invocador pode escolher uma carta inimiga em campo para roubar, desde que ela tenha menos de 5 de poder.','assets/cards-20261017/afrodite.png','Grécia',5,'greece'),
('aquiles','Aquiles','A Fúria de Mirmidão','Ao entrar em campo, ganha +1 de poder para cada soldado grego ou herói aliado em sua fileira.','assets/cards-20261017/aquiles.png','Grécia',3,'greece'),
('seth','Seth','Trovoada do Caos','Ao entrar em campo, escolhe uma fileira e troca os valores de poder de todas as cartas nela, aliadas e inimigas, de forma aleatória entre elas.','assets/cards-20261017/seth.png','Egípcios',4,'egypt'),
('osiris','Osíris','Justiça Cíclica','Ao ser destruído e enviado para o cemitério, dobra o poder de outra carta aliada aleatória em campo.','assets/cards-20261017/osiris.png','Egípcios',6,'egypt'),
('thor','Thor','Martelada de Mjölnir','Ao entrar em campo, escolhe a carta inimiga de maior poder e a envia para o Submundo.','assets/cards-20261017/thor.png','Nórdicos',6,'norse'),
('artemis','Ártemis','Tiro Preciso','Ao entrar em campo, elimina duas cartas Monstros de cada lado.','assets/cards-20261017/artemis.png','Grécia',5,'greece'),
('sobek','Sobek','Inundação Fertilizante','Ao entrar em campo, se houver outra carta aliada na mesma fileira, ganha +2 de poder adicional.','assets/cards-20261017/sobek.png','Egípcios',2,'egypt'),
('ares','Ares','Deus da Guerra','Ao entrar na Guerra, todos os Soldados de Esparta e Leônidas ganham 2 pontos de poder e todos os gregos ganham 1.','assets/cards-20261017/ares.png','Grécia',5,'greece'),
('beowulf','Beowulf','Coragem de Geat','Ao entrar em campo, se houver alguma carta da facção Monstros na mesa, ganha +3 pontos de poder adicional.','assets/cards-20261017/beowulf.png','Nórdicos',3,'norse'),
('heimdall','Heimdall','Vigília de Bifröst','Enquanto estiver em campo, nenhuma carta inimiga pode alterar o valor de poder das suas cartas nesta fileira.','assets/cards-20261017/heimdall.png','Nórdicos',3,'norse'),
('dionisio','Dionísio','Festival do Vinho','Todos os efeitos de cartas de ambos os lados ficam desativados por 3 rodadas.','assets/cards-20261017/dionisio.png','Grécia',4,'greece'),
('butter','Butter','Cleptomaníaco','Ao entrar em campo, rouba uma carta aleatória da mão do oponente.','assets/cards-20261017/butter.png','Alyns',4,'alyans'),
('hefesto','Hefestos','Melhoria Artefatual','Ao entrar em campo, aumenta em +3 os pontos de poder de um personagem com carta de equipamento.','assets/cards-20261017/hefesto.png','Grécia',4,'greece'),
('hercules','Hércules','Os Doze Trabalhos','A cada rodada ganha 1 de poder, podendo chegar a 16 pontos após 12 rodadas, concluindo seus doze trabalhos.','assets/cards-20261017/hercules.png','Grécia',4,'greece'),
('hermes','Hermes','Troca Veloz','Ao entrar em campo, você pode mover outra carta sua de uma fileira para outra, reorganizando sua pontuação.','assets/cards-20261017/hermes.png','Grécia',3,'greece'),
('horus','Hórus','Olho de Hórus','Ao entrar em campo, pode ver duas cartas do adversário.','assets/cards-20261017/horus.png','Egípcios',4,'egypt'),
('lobo-beta','Lobisomem Beta','Uivo do Betinha','Ao entrar em campo, chama os outros Betas que estiverem na mão do invocador para o campo.','assets/cards-20261017/lobo-beta.png','Monstros',2,'monster'),
('isis','Ísis','Ressurreição de Osíris','Ao entrar em campo, escolha uma carta com 2 ou menos de poder do seu próprio Submundo para retornar ao campo na fileira de Ísis.','assets/cards-20261017/isis.png','Egípcios',4,'egypt'),
('mulher','Mulher','Ainda Sou Alfa','Alfa sem poderes, usa sua labia para ganhar poder liderando homens humanos, cada homem dobra sua força.','assets/cards-20261017/mulher.png','Monstros',2,'monster'),
('homem','Homem','Juntos Somos Fortes','Ao perder os poderes, humanos se unem para duplicar suas forças.','assets/cards-20261017/homem.png','Monstros',1,'monster'),
('yggdrasil','Yggdrasil','Bônus de Terreno','Fortalece Odin em +2 de poder.','assets/terrains/yggdrasil.png','Nórdicos',0,'norse'),
('alto-egito','Alto Egito','Bônus de Terreno','Fortalece todos os egípcios em +2 de poder.','assets/terrains/alto-egito.jpg','Egípcios',0,'egypt'),
('baixo-egito','Baixo Egito','Bônus de Terreno','Fortalece todos os egípcios em +2 de poder.','assets/terrains/baixo-egito.png','Egípcios',0,'egypt'),
('bifrost','Bifrost','Bônus de Terreno','Fortalece todos os nórdicos, exceto Loki, em +2 de poder.','assets/terrains/bifrost.png','Nórdicos',0,'norse'),
('esparta','Esparta','Bônus de Terreno','Fortalece os espartanos em +2 de poder e Ares em +3 de poder.','assets/terrains/esparta.png','Grécia',0,'greece'),
('labirinto-dedalos','Labirinto de Dédalos','Bônus de Terreno','Fortalece o Minotauro e os monstros gregos em +2 de poder.','assets/terrains/labirinto-dedalos.png','Grécia',0,'greece'),
('nilfheim','Nilfheim','Bônus de Terreno','Fortalece Loki e os gigantes de gelo em +2 de poder.','assets/terrains/nilfheim.png','Nórdicos',0,'norse'),
('asgard','Asgard','Bônus de Local','Enquanto este Local estiver ativo, todos os nórdicos recebem +2 de poder, nos dois lados do campo.','assets/locations/asgard.png','Nórdicos',0,'norse'),
('egito','Egito','Bônus de Local','Enquanto este Local estiver ativo, todos os egípcios recebem +2 de poder, nos dois lados do campo.','assets/locations/egito.png','Egípcios',0,'egypt'),
('olho-que-tudo-ve','Olho que Tudo Vê','Equipar','Somente Hórus, Rá e Osíris podem equipar. Concede +4 de poder.','assets/equipment/olho-que-tudo-ve.png','Egípcios',0,'egypt'),
('raio-de-zeus','Raio de Zeus','Equipar','Somente Zeus pode equipar. Concede +4 de poder.','assets/equipment/raio-de-zeus.png','Grécia',0,'greece'),
('excalibur','Excalibur','Equipar','Somente Rei Arthur e Lukyan base podem equipar. Rei Arthur recebe +4 de poder. Lukyan base se transforma em Lukyan — Rei de Todos, uma carta especial que não entra no baralho nem na mão.','assets/equipment/excalibur.png','Universal',0,'celtic'),
('eclipse-lunar','Eclipse Lunar','Destino Celestial','Dobra o poder dos lobisomens, vampiros e de Ártemis. Apolo e Rá perdem metade do poder, arredondada para baixo.','assets/eclipse/eclipse-lunar.png','Universal',0,null),
('eclipse-solar','Eclipse Solar','Destino Celestial','Dobra o poder de Apolo e Rá. Vampiros vão ao Submundo; lobisomens Beta e Omega viram Homem, e Alfa vira Mulher. Ártemis perde metade do poder, arredondada para baixo.','assets/eclipse/eclipse-solar.png','Universal',0,null),
('loki','Loki','Ilusão Traiçoeira','Ao entrar em campo, Loki copia o valor de poder e a habilidade de uma carta inimiga já jogada na mesa até o fim da rodada.','assets/cards-20261017/loki.png','Nórdicos',3,'norse')
on conflict(card_id) do update set card_name=excluded.card_name,ability_title=excluded.ability_title,ability_text=excluded.ability_text,art_url=coalesce(excluded.art_url,public.card_lore.art_url),faction=excluded.faction,power=excluded.power,badge_key=coalesce(excluded.badge_key,public.card_lore.badge_key),updated_at=now();
