"thor"],"bonus":4},"olho-que-tudo-ve":{"ids":["horus","ra","osiris"],"bonus":4},"raio-de-zeus":{"ids":["zeus"],"bonus":4},"runas-nordicas":{"faction":"Nórdicos","bonus":2},"excalibur":{"ids":["rei-arthur","lukyan"],"bonus":4,"transformId":"lukyan","transformTo":"lukyan-rei-de-todos"}},"locations":{"asgard":"Nórdicos","egito":"Egípcios","grecia":"Grécia"},"special":["lukyan-rei-de-todos","eclipse-lunar","eclipse-solar"],"titles":{"revive":"Hades: escolha uma carta do seu Submundo","revive_cost":"Ísis: ressuscitar carta de até 2 de poder","anubis":"Anúbis: escolha um inimigo de até 3 de poder","anubis_revive":"Anúbis: recuperar carta de mesmo poder","steal":"Afrodite: escolha um inimigo com menos de 5 de poder","copy":"Loki: escolha qual inimigo copiar","move":"Hermes: escolha outro aliado","move_lane":"Hermes: escolha a nova fileira","rally":"Ragnar: reunir o aliado de menor poder","shuffle_lane":"Seth: escolha a fileira","improve":"Hefestos: escolha um aliado equipado","equip":"Escolha quem receberá o equipamento","foresight":"Odin: observar o topo do baralho","destroy_strongest":"Thor: escolha o inimigo de maior poder"}}$data$::jsonb $$;
create or replace function public._r_live(s jsonb) returns boolean language sql immutable set search_path='' as $$ select coalesce((s->>'round')::integer,1)>coalesce((s->>'silenceUntilRound')::integer,0) $$;
create or replace function public._r_id(u jsonb) returns text language sql immutable set search_path='' as $$ select coalesce(u->>'copiedAbilityId',u->>'cardId') $$;
create or replace function public._r_other(t text) returns text language sql immutable set search_path='' as $$ select case when t='player_one' then 'player_two' else 'player_one' end; $$;
create or replace function public._r_unit(s jsonb,t text,id text) returns jsonb language sql immutable set search_path='' as $$ select value from jsonb_array_elements(coalesce(s#>array[t,'field'],'[]'::jsonb)) where value->>'uid'=id limit 1 $$;
create or replace function public._r_protect(s jsonb,t text,l integer,src text) returns boolean language sql immutable set search_path='' as $$ select public._r_live(s) and src<>t and exists(select 1 from jsonb_array_elements(coalesce(s#>array[t,'field'],'[]'::jsonb)) a(value) where coalesce((a.value->>'lane')::integer,0)=l and public._r_id(a.value)='heimdall') $$;
create or replace function public._r_equip(id text,u jsonb) returns boolean language sql immutable set search_path='' as $$ select coalesce(case when (public._r_data()#>array['equipment',id]) ? 'ids' then (public._r_data()#>array['equipment',id,'ids']) ? (u->>'cardId') else public._r_data()#>>array['equipment',id,'faction']=public._r_card(u->>'cardId')->>'faction' end,false) $$;
create or replace function public._r_power(s jsonb,t text,u jsonb,depth integer default 0)
returns numeric language plpgsql stable set search_path='' as $$
declare c jsonb:=public._r_card(u->>'cardId'); a jsonb:=s->t; id text:=public._r_id(u); p numeric:=coalesce((c->>'power')::numeric,0); n integer; item jsonb; gear text; r jsonb; climate text:=s#>>'{sharedZones,climate}'; enemy numeric;
begin
 if not public._r_live(s) then return p;end if;
 p:=coalesce((u->>'copiedPower')::numeric,p)+coalesce((u->>'bonus')::numeric,0);
 if id='hercules' then p:=p+least(12,coalesce((u->>'progress')::integer,0));end if;
 for gear in select jsonb_array_elements_text(coalesce(u->'equipment','[]'::jsonb)) loop if public._r_equip(gear,u) then p:=p+coalesce((public._r_data()#>>array['equipment',gear,'bonus'])::integer,0);end if;end loop;
 if id='soldado-esparta' then select count(*)::integer into n from jsonb_array_elements(a->'field') v where v->>'cardId'='soldado-esparta' and v->>'uid'<>u->>'uid';p:=p*power(2::numeric,n);end if;
 if id='lobo-alfa' then p:=p+2*(select count(*) from jsonb_array_elements(a->'field') v where v->>'cardId'='lobo-beta');end if;
 p:=p+2*(select count(*) from jsonb_array_elements(a->'field') v where v->>'uid'<>u->>'uid' and public._r_id(v)='athena' and (v->>'lane')::integer=(u->>'lane')::integer);
 if id='lobo-omega' and depth=0 and (select count(*) from jsonb_array_elements(a->'field') v where v->>'lane'=u->>'lane')=1 then
  select coalesce(sum(public._r_power(s,public._r_other(t),v,1)),0) into enemy from jsonb_array_elements(coalesce(s#>array[public._r_other(t),'field'],'[]'::jsonb)) v where v->>'lane'=u->>'lane';if enemy>p then p:=p+8;end if;
 end if;
 if id in ('mulher','homem') then select count(*)::integer into n from jsonb_array_elements(a->'field') v where v->>'cardId'='homem' and (id='mulher' or v->>'uid'<>u->>'uid');p:=p*power(2::numeric,n);end if;
 p:=p*coalesce((u->>'multiplier')::numeric,1);
 if not public._r_protect(s,t,(u->>'lane')::integer,coalesce(s#>>'{zoneOwners,local}',t)) and public._r_data()#>>array['locations',s#>>'{sharedZones,local}']=c->>'faction' then p:=p+2;end if;
 if not public._r_protect(s,t,(u->>'lane')::integer,coalesce(s#>>'{zoneOwners,terrain}',t)) then p:=p+public._terrain_bonus(s#>>'{sharedZones,terrain}',u->>'cardId');end if;
 if c->>'faction'='Grécia' then p:=p+coalesce((a->>'greekAura')::numeric,0);end if;if c->>'faction'='Nórdicos' then p:=p+coalesce((a->>'norseAura')::numeric,0);end if;
 if id='lukyan-rei-de-todos' then p:=p*power(2::numeric,greatest(0,jsonb_array_length(a->'field')-1));end if;
 if not public._r_protect(s,t,(u->>'lane')::integer,coalesce(s#>>'{zoneOwners,climate}',t)) then
  if climate='eclipse-lunar' then if u->>'cardId' in ('lobo-alfa','lobo-beta','lobo-omega','artemis') or public._eclipse_is_vampire(u->>'cardId') then p:=p*2;end if;if u->>'cardId' in ('apolo','ra') then p:=floor(p/2);end if;
  elsif climate='eclipse-solar' then if u->>'cardId' in ('apolo','ra') then p:=p*2;end if;if u->>'cardId'='artemis' then p:=floor(p/2);end if;end if;
 end if;
 return greatest(0,floor(p+coalesce((u->>'powerShift')::numeric,0)));
end; $$;

create or replace function public._r_grave_ok(x jsonb,e jsonb,g jsonb) returns boolean language plpgsql stable set search_path='' as $$
declare c jsonb:=public._r_card(g->>'cardId'); zone text;
begin
 if c='{}'::jsonb or coalesce((c->>'specialOnly')::boolean,false) or g->>'owner' is distinct from e->>'owner' then return false;end if;
 if e->>'op'='revive_cost' and coalesce((c->>'power')::numeric,0)>2 then return false;end if;
 if e->>'op'='anubis_revive' and coalesce((c->>'power')::numeric,0)<>(e->>'wantedPower')::numeric then return false;end if;
 if c->>'kind'='unit' then return true;end if;
 if c->>'kind'='equipment' then return exists(select 1 from jsonb_array_elements(x#>array['s',e->>'team','field']) a where public._r_equip(g->>'cardId',a));end if;
 zone:=case c->>'kind' when 'location' then 'local' when 'terrain' then 'terrain' else 'climate' end;
 return x#>>array['s','sharedZones',zone] is null;
end; $$;
create or replace function public._r_option(v text,label text,cid text default null) returns jsonb language sql immutable set search_path='' as $$ select jsonb_build_object('value',v,'label',label,'cardId',cid) $$;
create or replace function public._r_options(x jsonb,e jsonb) returns jsonb language plpgsql stable set search_path='' as $$
declare op text:=e->>'op'; t text:=e->>'team'; enemy text:=public._r_other(t); result jsonb:='[]'::jsonb; candidate jsonb; source_team text; p numeric; extreme numeric; include_it boolean; i integer; cid text;
begin
 if op in ('revive','revive_cost','anubis_revive') then
  for candidate in select value from jsonb_array_elements(x#>array['s',t,'grave']) where public._r_grave_ok(x,e,value) loop cid:=candidate->>'cardId';result:=result||jsonb_build_array(public._r_option(candidate->>'uid',public._r_card(cid)->>'name',cid));end loop;
  return result||jsonb_build_array(public._r_option('skip','Não ressuscitar'));
 end if;
 if op in ('move_lane','shuffle_lane') then for i in 0..2 loop if op='shuffle_lane' or i<>(e->>'fromLane')::integer then result:=result||jsonb_build_array(public._r_option(i::text,'Fileira '||(i+1)::text));end if;end loop;return result;end if;
 if op='foresight' then if jsonb_array_length(coalesce(x#>array['r',e->>'owner','deck'],'[]'::jsonb))=0 then return result;end if;return jsonb_build_array(public._r_option('discard','Descartar o topo e ganhar +2 na soma'),public._r_option('keep','Manter no topo'));end if;
 if op not in ('copy','steal','anubis','destroy_strongest','move','rally','improve','equip') then return null;end if;
 source_team:=case when op in ('copy','steal','anubis','destroy_strongest') then enemy else t end;
 if op='destroy_strongest' then select max(public._r_power(x->'s',source_team,value)) into extreme from jsonb_array_elements(x#>array['s',source_team,'field']);end if;
 if op='rally' then select min(public._r_power(x->'s',t,value)) into extreme from jsonb_array_elements(x#>array['s',t,'field']) where value->>'lane'<>e->>'lane';end if;
 for candidate in select value from jsonb_array_elements(x#>array['s',source_team,'field']) loop
  p:=public._r_power(x->'s',source_team,candidate);
  include_it:=case op when 'copy' then true when 'steal' then p<5 when 'anubis' then p<=3 when 'destroy_strongest' then p=extreme when 'move' then candidate->>'uid'<>e->>'uid' when 'rally' then candidate->>'lane'<>e->>'lane' and p=extreme when 'improve' then jsonb_array_length(coalesce(candidate->'equipment','[]'::jsonb))>0 when 'equip' then public._r_equip(e->>'cardId',candidate) else false end;
  if include_it then cid:=candidate->>'cardId';result:=result||jsonb_build_array(public._r_option(candidate->>'uid',coalesce(public._r_card(cid)->>'name',cid)||' · '||p::text||' poder · Fileira '||(((candidate->>'lane')::integer+1)::text),cid));end if;
 end loop;
 if op in ('steal','move') then result:=result||jsonb_build_array(public._r_option('skip',case when op='steal' then 'Não roubar' else 'Não mover' end));end if;return result;
end; $$;

create or replace function public._r_resolve(x jsonb,e jsonb) returns jsonb language plpgsql volatile set search_path='' as $$
declare op text:=e->>'op'; t text:=e->>'team'; enemy text:=public._r_other(t); owner_id text:=e->>'owner'; selected text:=e->>'selection'; lane integer:=coalesce((e->>'lane')::integer,0); u jsonb:=public._r_unit(x->'s',t,e->>'uid'); target jsonb; v jsonb; g jsonb; cid text; team text; id text; command text; amount numeric; wanted numeric; ids jsonb; list jsonb; vals jsonb; row_item jsonb; n integer; i integer; j integer; res jsonb; chosen_owner text;
begin
 if not public._r_live(x->'s') then return x;end if;
 if op not in ('osiris','equip','anubis_revive','move_lane') and u is null then return x;end if;
 case op
 when 'copy' then
  target:=public._r_unit(x->'s',enemy,selected);if target is null then return x;end if;
  u:=u||jsonb_build_object('copiedPower',public._r_power(x->'s',enemy,target),'copiedAbilityId',public._r_id(target),'copiedFrom',target->>'cardId');x:=public._r_set_unit(x,t,u->>'uid',u);
  if public._r_id(u)<>'loki' then for command in select jsonb_array_elements_text(coalesce(public._r_data()#>array['entries',public._r_id(u)],'[]'::jsonb)) loop x:=public._r_evt(x,e-'selection'||jsonb_build_object('op',command));end loop;end if;
 when 'revive','revive_cost','anubis_revive' then
  if selected='skip' then return x;end if;
  select value into g from jsonb_array_elements(x#>array['s',t,'grave']) where value->>'uid'=selected limit 1;
  if g is null or not public._r_grave_ok(x,e,g) then raise exception 'Esta carta não pode ser ressuscitada.';end if;
  x:=jsonb_set(x,array['s',t,'grave'],coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['s',t,'grave']) with ordinality a(value,ordinality) where value->>'uid'<>selected),'[]'::jsonb),true);x:=public._r_grave_sync(x,t);
  x:=public._r_spawn(x,g->>'cardId',t,owner_id,lane,coalesce((g->>'progress')::integer,0));
 when 'steal' then
  if selected='skip' then return x;end if;target:=public._r_unit(x->'s',enemy,selected);if target is null or public._r_power(x->'s',enemy,target)>=5 then raise exception 'Alvo fora da regra de Afrodite.';end if;
  x:=jsonb_set(x,array['s',enemy,'field'],coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['s',enemy,'field']) with ordinality a(value,ordinality) where value->>'uid'<>selected),'[]'::jsonb),true);
  target:=target||jsonb_build_object('playedBy',owner_id,'uid',pg_catalog.gen_random_uuid()::text);x:=jsonb_set(x,array['s',t,'field'],(x#>array['s',t,'field'])||jsonb_build_array(target),true);
 when 'anubis' then
  target:=public._r_unit(x->'s',enemy,selected);if target is null then return x;end if;wanted:=public._r_power(x->'s',enemy,target);x:=public._r_destroy(x,enemy,jsonb_build_array(selected));x:=public._r_evt(x,e-'selection'||jsonb_build_object('op','anubis_revive','wantedPower',wanted));
 when 'destroy_strongest' then x:=public._r_destroy(x,enemy,jsonb_build_array(selected));
 when 'destroy_two' then
  select coalesce(jsonb_agg(value->'uid'),'[]'::jsonb) into ids from (select value from jsonb_array_elements(x#>array['s',enemy,'field']) order by public._r_power(x->'s',enemy,value) desc limit 2) a;x:=public._r_destroy(x,enemy,ids);
 when 'hunt_monsters' then
  foreach team in array array['player_one','player_two'] loop select coalesce(jsonb_agg(value->'uid'),'[]'::jsonb) into ids from (select value from jsonb_array_elements(x#>array['s',team,'field']) where (public._r_card(value->>'cardId')->'tags') ? 'monstro' order by public._r_power(x->'s',team,value) desc limit 2) a;x:=public._r_destroy(x,team,ids);end loop;
 when 'petrify' then
  chosen_owner:=null;
  if jsonb_array_length(coalesce(x#>'{s,turnOrder}','[]'::jsonb))>0 then
   n:=jsonb_array_length(x#>'{s,turnOrder}');for i in 1..n loop id:=x#>>array['s','turnOrder',mod(coalesce((x#>>'{s,currentTurnIndex}')::integer,0)+i,n)::text];if x#>>array['r',id,'team']=enemy and not coalesce((x#>>array['r',id,'passed'])::boolean,false) then chosen_owner:=id;exit;end if;end loop;
  else select key into chosen_owner from jsonb_each(x->'r') where value->>'team'=enemy and not coalesce((value->>'passed')::boolean,false) order by key limit 1;end if;
  if chosen_owner is not null then x:=jsonb_set(x,array['r',chosen_owner,'skipNextTurn'],'true'::jsonb,true);end if;
 when 'tsunami' then
  for v in select value from jsonb_array_elements(x#>array['s',enemy,'field']) where coalesce((value->>'lane')::integer,0)=0 loop x:=public._r_change(x,enemy,v->>'uid',t,-2);end loop;
 when 'move' then
  if selected='skip' then return x;end if;target:=public._r_unit(x->'s',t,selected);if target is not null then x:=public._r_evt(x,jsonb_build_object('op','move_lane','team',t,'owner',owner_id,'lane',lane,'targetUid',selected,'fromLane',(target->>'lane')::integer));end if;
 when 'move_lane' then target:=public._r_unit(x->'s',t,e->>'targetUid');if target is not null then x:=public._r_set_unit(x,t,target->>'uid',jsonb_set(target,'{lane}',to_jsonb(selected::integer),true));end if;
 when 'rally' then target:=public._r_unit(x->'s',t,selected);if target is not null then x:=public._r_set_unit(x,t,selected,jsonb_set(target,'{lane}',to_jsonb(lane),true));end if;
 when 'shuffle_lane' then
  list:='[]'::jsonb;foreach team in array array['player_one','player_two'] loop for v in select value from jsonb_array_elements(x#>array['s',team,'field']) where (value->>'lane')::integer=selected::integer loop if not public._r_protect(x->'s',team,selected::integer,t) then list:=list||jsonb_build_array(jsonb_build_object('team',team,'uid',v->>'uid','power',public._r_power(x->'s',team,v)));end if;end loop;end loop;
  select coalesce(jsonb_agg(value->'power' order by random()),'[]'::jsonb) into vals from jsonb_array_elements(list);i:=0;for row_item in select value from jsonb_array_elements(list) loop target:=public._r_unit(x->'s',row_item->>'team',row_item->>'uid');target:=jsonb_set(target,'{powerShift}',to_jsonb(coalesce((target->>'powerShift')::numeric,0)+(vals->>i)::numeric-(row_item->>'power')::numeric),true);x:=public._r_set_unit(x,row_item->>'team',row_item->>'uid',target);i:=i+1;end loop;
 when 'improve' then x:=public._r_change(x,t,selected,t,3);
 when 'equip' then
  target:=public._r_unit(x->'s',t,selected);if target is null or not public._r_equip(e->>'cardId',target) then raise exception 'Equipamento incompatível.';end if;target:=jsonb_set(target,'{equipment}',coalesce(target->'equipment','[]'::jsonb)||jsonb_build_array(e->>'cardId'),true);x:=public._r_set_unit(x,t,selected,target);
 when 'schedule_foresight' then x:=public._r_set_unit(x,t,u->>'uid',jsonb_set(u,'{odinReady}','true'::jsonb,true));
 when 'foresight' then
  res:=x#>array['r',owner_id];if selected='discard' and jsonb_array_length(res->'deck')>0 then cid:=res#>>'{deck,0}';res:=jsonb_set(res,'{deck}',(res->'deck')-0,true);x:=jsonb_set(x,array['r',owner_id],res,true);x:=jsonb_set(x,array['s',t,'grave'],(x#>array['s',t,'grave'])||jsonb_build_array(jsonb_build_object('uid',pg_catalog.gen_random_uuid()::text,'cardId',cid,'owner',owner_id,'progress',0)),true);x:=public._r_grave_sync(x,t);x:=jsonb_set(x,array['s',t,'roundScoreBonus'],to_jsonb(coalesce((x#>>array['s',t,'roundScoreBonus'])::numeric,0)+2),true);end if;
 when 'reveal','steal_hand' then
  list:='[]'::jsonb;for row_item in select jsonb_build_object('owner',key,'res',value) from jsonb_each(x->'r') where value->>'team'=enemy loop i:=0;for v in select value from jsonb_array_elements(coalesce(row_item#>'{res,hand}','[]'::jsonb)) loop list:=list||jsonb_build_array(jsonb_build_object('owner',row_item->>'owner','cardId',v#>>'{}','index',i));i:=i+1;end loop;end loop;
  if op='reveal' then select coalesce(jsonb_agg(value->'cardId'),'[]'::jsonb) into vals from (select value from jsonb_array_elements(list) order by random() limit 2) a;x:=jsonb_set(x,array['r',owner_id,'privateEffects'],jsonb_build_object('id',pg_catalog.gen_random_uuid()::text,'kind','reveal','cards',vals),true);
  elsif jsonb_array_length(list)>0 then target:=list->floor(random()*jsonb_array_length(list))::integer;x:=jsonb_set(x,array['r',target->>'owner','hand'],(x#>array['r',target->>'owner','hand'])-(target->>'index')::integer,true);x:=jsonb_set(x,array['r',owner_id,'hand'],(x#>array['r',owner_id,'hand'])||jsonb_build_array(target->>'cardId'),true);end if;
 when 'silence' then
  x:=jsonb_set(x,'{s,silenceUntilRound}',to_jsonb((x#>>'{s,round}')::integer+2),true);x:=jsonb_set(x,'{s,effectQueue}','[]'::jsonb,true);
  foreach team in array array['player_one','player_two'] loop for v in select value from jsonb_array_elements(x#>array['s',team,'field']) loop if v ? 'eclipseOriginalCardId' then target:=(v-'eclipseOriginalCardId')||jsonb_build_object('cardId',v->>'eclipseOriginalCardId');x:=public._r_set_unit(x,team,v->>'uid',target);end if;end loop;end loop;
  for chosen_owner in select key from jsonb_each(x->'r') loop x:=jsonb_set(x,array['r',chosen_owner,'skipNextTurn'],'false'::jsonb,true);end loop;
 when 'double_lane' then for v in select value from jsonb_array_elements(x#>array['s',t,'field']) where (value->>'lane')::integer=lane loop x:=public._r_change(x,t,v->>'uid',t,0,2);end loop;
 when 'war_buff' then for v in select value from jsonb_array_elements(x#>array['s',t,'field']) loop g:=public._r_card(v->>'cardId');amount:=case when (g->'tags') ? 'espartano' or v->>'cardId'='leonidas' then 2 when g->>'faction'='Grécia' then 1 else 0 end;x:=public._r_change(x,t,v->>'uid',t,amount);end loop;
 when 'crowd_bonus' then if exists(select 1 from jsonb_array_elements(x#>array['s',t,'field']) a where a->>'uid'<>u->>'uid' and (a->>'lane')::integer=lane) then x:=public._r_change(x,t,u->>'uid',t,3);end if;
 when 'alone_bonus' then if (select count(*) from jsonb_array_elements(x#>array['s',t,'field']) a where (a->>'lane')::integer=lane)=1 then x:=public._r_change(x,t,u->>'uid',t,3);end if;
 when 'ally_bonus' then if exists(select 1 from jsonb_array_elements(x#>array['s',t,'field']) a where a->>'uid'<>u->>'uid' and (a->>'lane')::integer=lane) then x:=public._r_change(x,t,u->>'uid',t,2);end if;
 when 'greek_bonus' then select count(*) into n from jsonb_array_elements(x#>array['s',t,'field']) a where a->>'uid'<>u->>'uid' and (a->>'lane')::integer=lane and public._r_card(a->>'cardId')->>'faction'='Grécia' and (public._r_card(a->>'cardId')->'tags') ?| array['heroi','soldado','espartano'];x:=public._r_change(x,t,u->>'uid',t,n);
 when 'monster_bonus' then if exists(select 1 from jsonb_array_elements((x#>'{s,player_one,field}')||(x#>'{s,player_two,field}')) a where public._r_card(a->>'cardId')->>'faction'='Monstros') then x:=public._r_change(x,t,u->>'uid',t,3);end if;
 when 'summon_betas' then
  res:=x#>array['r',owner_id];n:=(select count(*) from jsonb_array_elements_text(res->'hand') a where a='lobo-beta');select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into ids from jsonb_array_elements(res->'hand') with ordinality a(value,ordinality) where value<>'"lobo-beta"'::jsonb;x:=jsonb_set(x,array['r',owner_id,'hand'],ids,true);for i in 1..n loop x:=public._r_spawn(x,'lobo-beta',t,owner_id,lane);end loop;
 when 'osiris' then
  list:=x#>array['s',t,'field'];if jsonb_array_length(list)>0 then target:=list->floor(random()*jsonb_array_length(list))::integer;x:=public._r_change(x,t,target->>'uid',t,0,2);end if;
 else null;
 end case;
 return public._r_reconcile(x);
end; $$;
create or replace function public._r_score(s jsonb,t text) returns numeric language sql stable set search_path='' as $$ select greatest(0,coalesce((select sum(public._r_power(s,t,v)) from jsonb_array_elements(coalesce(s#>array[t,'field'],'[]'::jsonb)) v),0)+case when public._r_live(s) then coalesce((s#>>array[t,'roundScoreBonus'])::numeric,0) else 0 end) $$;
create or replace function public._r_set_unit(x jsonb,t text,id text,u jsonb) returns jsonb language sql immutable set search_path='' as $$ select jsonb_set(x,array['s',t,'field'],coalesce((select jsonb_agg(case when value->>'uid'=id then u else value end order by ordinality) from jsonb_array_elements(x#>array['s',t,'field']) with ordinality a(value,ordinality)),'[]'::jsonb),true) $$;
create or replace function public._r_grave_sync(x jsonb,t text) returns jsonb language sql immutable set search_path='' as $$ select jsonb_set(x,array['s',t,'underworld'],coalesce((select jsonb_agg(value->'cardId' order by ordinality) from jsonb_array_elements(coalesce(x#>array['s',t,'grave'],'[]'::jsonb)) with ordinality a(value,ordinality)),'[]'::jsonb),true) $$;
create or replace function public._r_evt(x jsonb,e jsonb) returns jsonb language sql immutable set search_path='' as $$ select jsonb_set(x,'{s,effectQueue}',coalesce(x#>'{s,effectQueue}','[]'::jsonb)||jsonb_build_array(e),true) $$;
create or replace function public._r_change(x jsonb,t text,id text,src text,amount numeric default 0,mult numeric default 1) returns jsonb language plpgsql immutable set search_path='' as $$
declare u jsonb:=public._r_unit(x->'s',t,id);
begin if u is null or public._r_protect(x->'s',t,(u->>'lane')::integer,src) then return x;end if;u:=jsonb_set(u,'{bonus}',to_jsonb(coalesce((u->>'bonus')::numeric,0)+amount),true);u:=jsonb_set(u,'{multiplier}',to_jsonb(coalesce((u->>'multiplier')::numeric,1)*mult),true);return public._r_set_unit(x,t,id,u);end; $$;
create or replace function public._r_destroy(x jsonb,t text,ids jsonb,killed boolean default true) returns jsonb language plpgsql volatile set search_path='' as $$
declare u jsonb; grave jsonb:=coalesce(x#>array['s',t,'grave'],'[]'::jsonb); gear text; original text;
begin
 if coalesce((resources#>>array[actor,'skipNextTurn'])::boolean,false) then return x;end if;
 for u in select value from jsonb_array_elements(coalesce(x#>array['s',t,'field'],'[]'::jsonb)) a(value) where ids ? (a.value->>'uid') loop
  original:=coalesce(u->>'eclipseOriginalCardId',u->>'sourceCardId',case when u->>'cardId'='lukyan-rei-de-todos' then 'lukyan' else u->>'cardId' end);
  grave:=grave||jsonb_build_array(jsonb_build_object('uid',pg_catalog.gen_random_uuid()::text,'cardId',original,'owner',u->>'playedBy','progress',coalesce((u->>'progress')::integer,0),'deathPower',public._r_power(x->'s',t,u)));
  for gear in select jsonb_array_elements_text(coalesce(u->'equipment','[]'::jsonb)) loop grave:=grave||jsonb_build_array(jsonb_build_object('uid',pg_catalog.gen_random_uuid()::text,'cardId',gear,'owner',u->>'playedBy','progress',0));end loop;
  if killed and public._r_live(x->'s') and public._r_id(u)='osiris' then x:=public._r_evt(x,jsonb_build_object('op','osiris','team',t,'owner',u->>'playedBy','lane',0));end if;
 end loop;
 x:=jsonb_set(x,array['s',t,'grave'],grave,true);
 x:=jsonb_set(x,array['s',t,'field'],coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['s',t,'field']) with ordinality a(value,ordinality) where not(ids ? (a.value->>'uid'))),'[]'::jsonb),true);
 return public._r_grave_sync(x,t);
end; $$;
create or replace function public._r_reconcile(x jsonb) returns jsonb language plpgsql volatile set search_path='' as $$
declare t text; u jsonb; form text;
begin if not public._r_live(x->'s') then return x;end if;
 foreach t in array array['player_one','player_two'] loop for u in select value from jsonb_array_elements(x#>array['s',t,'field']) loop
  if u->>'cardId'='lukyan' and (u->'equipment') ? 'excalibur' then u:=u||jsonb_build_object('sourceCardId','lukyan','cardId','lukyan-rei-de-todos');x:=public._r_set_unit(x,t,u->>'uid',u);end if;
  if x#>>'{s,sharedZones,climate}' is distinct from 'eclipse-solar' then continue;end if;
  if public._eclipse_is_vampire(u->>'cardId') then x:=public._r_destroy(x,t,jsonb_build_array(u->>'uid'));continue;end if;
  if public._r_protect(x->'s',t,(u->>'lane')::integer,coalesce(x#>>'{s,zoneOwners,climate}',t)) then continue;end if;
  form:=case u->>'cardId' when 'lobo-alfa' then 'mulher' when 'lobo-beta' then 'homem' when 'lobo-omega' then 'homem' end;
  if form is not null then u:=(u-'copiedAbilityId'-'copiedPower')||jsonb_build_object('eclipseOriginalCardId',u->>'cardId','cardId',form);x:=public._r_set_unit(x,t,u->>'uid',u);end if;
 end loop;end loop;return x;
end; $$;
create or replace function public._r_spawn(x jsonb,cid text,t text,owner_id text,lane integer,progress integer default 0) returns jsonb language plpgsql volatile set search_path='' as $$
declare c jsonb:=public._r_card(cid); u jsonb; op text; zone text; result text;
begin
 if c='{}'::jsonb or coalesce((c->>'specialOnly')::boolean,false) then raise exception 'Carta especial indisponível.';end if;
 if c->>'kind'='unit' then
  u:=jsonb_build_object('uid',pg_catalog.gen_random_uuid()::text,'cardId',cid,'playedBy',owner_id,'lane',lane,'slot',jsonb_array_length(x#>array['s',t,'field']),'bonus',0,'multiplier',1,'equipment','[]'::jsonb,'progress',progress);
  x:=jsonb_set(x,array['s',t,'field'],(x#>array['s',t,'field'])||jsonb_build_array(u),true);x:=public._r_reconcile(x);u:=public._r_unit(x->'s',t,u->>'uid');
  if u is not null and public._r_live(x->'s') then for op in select jsonb_array_elements_text(coalesce(public._r_data()#>array['entries',public._r_id(u)],'[]'::jsonb)) loop x:=public._r_evt(x,jsonb_build_object('op',op,'team',t,'owner',owner_id,'uid',u->>'uid','lane',lane));end loop;end if;
 elsif c->>'kind'='equipment' then if public._r_live(x->'s') then x:=public._r_evt(x,jsonb_build_object('op','equip','team',t,'owner',owner_id,'cardId',cid,'lane',lane));end if;
 else
  zone:=case c->>'kind' when 'location' then 'local' when 'terrain' then 'terrain' else 'climate' end;
  if x#>>array['s','sharedZones',zone] is not null then raise exception 'O espaço compartilhado já está ocupado.';end if;
  x:=jsonb_set(x,array['s','zoneOwners',zone],to_jsonb(t),true);
  if cid='eclipse' then result:=case when random()<0.5 then 'eclipse-lunar' else 'eclipse-solar' end;x:=jsonb_set(x,'{s,sharedZones,climate}',to_jsonb(result),true);x:=jsonb_set(x,'{s,eclipseReveal}',jsonb_build_object('id',pg_catalog.gen_random_uuid()::text,'outcome',result,'round',x#>'{s,round}'),true);
  else x:=jsonb_set(x,array['s','sharedZones',zone],to_jsonb(cid),true);end if;x:=public._r_reconcile(x);
 end if;return x;
end; $$;

create or replace function public._r_init(s jsonb,resources jsonb) returns jsonb language plpgsql volatile set search_path='' as $$
declare x jsonb; t text; a jsonb; u jsonb; field jsonb; grave jsonb; id text; owner_id text; owner_count integer; i integer;
begin
 if s->'pendingEffect'='null'::jsonb then s:=s-'pendingEffect';end if;
 s:=jsonb_set(s,'{effectQueue}',coalesce(s->'effectQueue','[]'::jsonb),true);s:=jsonb_set(s,'{zoneOwners}',coalesce(s->'zoneOwners','{}'::jsonb),true);x:=jsonb_build_object('s',s,'r',resources);
 foreach t in array array['player_one','player_two'] loop
  a:=coalesce(s->t,'{}'::jsonb);select count(*)::integer,min(key) into owner_count,owner_id from jsonb_each(resources) where value->>'team'=t;if owner_count<>1 then owner_id:=null;end if;
  field:='[]'::jsonb;for u in select value from jsonb_array_elements(coalesce(a->'field','[]'::jsonb)) loop u:=jsonb_build_object('bonus',0,'multiplier',1,'equipment','[]'::jsonb,'lane',0,'playedBy',owner_id)||u;if coalesce(u->>'uid','')='' then u:=jsonb_set(u,'{uid}',to_jsonb(pg_catalog.gen_random_uuid()::text),true);end if;field:=field||jsonb_build_array(u);end loop;
  a:=jsonb_set(a,'{field}',field,true);
  if not(a ? 'grave') then grave:='[]'::jsonb;i:=0;for id in select jsonb_array_elements_text(coalesce(a->'underworld','[]'::jsonb)) loop grave:=grave||jsonb_build_array(jsonb_build_object('uid','legacy:'||t||':'||i::text,'cardId',id,'owner',owner_id,'progress',0));i:=i+1;end loop;a:=jsonb_set(a,'{grave}',grave,true);end if;
  x:=jsonb_set(x,array['s',t],a,true);x:=public._r_grave_sync(x,t);
 end loop;return x;
end; $$;
create or replace function public._r_drain(x jsonb,auto_choose boolean default false) returns jsonb language plpgsql volatile set search_path='' as $$
declare e jsonb; opts jsonb; pending jsonb; count_steps integer:=0;
begin
 while jsonb_array_length(x#>'{s,effectQueue}')>0 and x#>'{s,pendingEffect}' is null loop
  count_steps:=count_steps+1;if count_steps>256 then raise exception 'Sequência de habilidades longa demais.';end if;
  e:=x#>'{s,effectQueue,0}';x:=jsonb_set(x,'{s,effectQueue}',(x#>'{s,effectQueue}')-0,true);if not public._r_live(x->'s') then continue;end if;
  opts:=public._r_options(x,e);
  if opts is not null and not(e ? 'selection') then
   if jsonb_array_length(opts)=0 then continue;end if;
   if auto_choose then e:=e||jsonb_build_object('selection',opts#>>'{0,value}');
   else pending:=jsonb_build_object('id',pg_catalog.gen_random_uuid()::text,'actor',e->>'owner','event',e,'options',opts,'title',coalesce(public._r_data()#>>array['titles',e->>'op'],'Escolha o alvo'));x:=jsonb_set(x,'{s,pendingEffect}',pending,true);exit;end if;
  end if;
  x:=public._r_resolve(x,e);
 end loop;return x;
end; $$;
create or replace function public._r_turn_start(s jsonb,resources jsonb,actor text) returns jsonb language plpgsql volatile set search_path='' as $$
declare x jsonb:=public._r_init(s,resources);t text:=resources#>>array[actor,'team'];u jsonb;
begin
 if coalesce((resources#>>array[actor,'skipNextTurn'])::boolean,false) then return x;end if;
 for u in select value from jsonb_array_elements(coalesce(x#>array['s',t,'field'],'[]'::jsonb)) loop
  if u->>'playedBy'=actor and coalesce((u->>'odinReady')::boolean,false) then
   x:=public._r_set_unit(x,t,u->>'uid',u-'odinReady');x:=public._r_evt(x,jsonb_build_object('op','foresight','team',t,'owner',actor,'uid',u->>'uid','lane',u->'lane'));
  end if;
 end loop;
 x:=public._r_drain(x);if x#>'{s,pendingEffect}' is not null then x:=jsonb_set(x,'{s,abilityPhase}','"turn_start"'::jsonb,true);end if;return x;
end; $$;
create or replace function public._r_finish_start(x jsonb,actor text) returns jsonb language plpgsql volatile set search_path='' as $$
declare r jsonb:=x#>array['r',actor];
begin
 if x#>'{s,pendingEffect}' is not null then return x;end if;
 if mod(coalesce((r->>'turnsTaken')::integer,0),2)=1 and jsonb_array_length(coalesce(r->'deck','[]'::jsonb))>0 then
  r:=jsonb_set(r,'{hand}',coalesce(r->'hand','[]'::jsonb)||jsonb_build_array(r#>'{deck,0}'),true);r:=jsonb_set(r,'{deck}',(r->'deck')-0,true);
 end if;x:=jsonb_set(x,array['r',actor],r,true);return x#-'{s,abilityPhase}';
end; $$;
create or replace function public._r_action(s jsonb,resources jsonb,actor text,a jsonb) returns jsonb language plpgsql volatile set search_path='' as $$
declare x jsonb:=public._r_init(s,resources); res jsonb; t text; pending jsonb; e jsonb; cid text:=a->>'card_id'; c jsonb; idx integer; hand jsonb; lane integer;
begin
 res:=x#>array['r',actor];t:=res->>'team';if t is null or t not in ('player_one','player_two') or res is null then raise exception 'Invocador inválido.';end if;
 pending:=x#>'{s,pendingEffect}';
 if a->>'type' in ('pass','skip_turn') and pending is not null then
  if pending->>'actor'<>actor then raise exception 'A escolha pertence a outro invocador.';end if;e:=(pending->'event')||jsonb_build_object('selection',pending#>>'{options,0,value}');x:=x#-'{s,pendingEffect}';x:=jsonb_set(x,'{s,effectQueue}',jsonb_build_array(e)||(x#>'{s,effectQueue}'),true);x:=public._r_drain(x,true);x:=x#-'{s,abilityPhase}';if a->>'type'='pass' then return jsonb_set(x,array['r',actor,'passed'],'true'::jsonb,true);end if;x:=jsonb_set(x,array['r',actor,'skipNextTurn'],'false'::jsonb,true);return jsonb_set(x,array['r',actor,'playedThisTurn'],'true'::jsonb,true);
 end if;
 if a->>'type'='resolve_effect' then
  if pending is null or pending->>'actor'<>actor or pending->>'id' is distinct from a->>'choice_id' then raise exception 'Escolha indisponível.';end if;
  if not exists(select 1 from jsonb_array_elements(pending->'options') v where v->>'value'=a->>'choice_value') then raise exception 'Escolha inválida.';end if;
  e:=(pending->'event')||jsonb_build_object('selection',a->>'choice_value');x:=x#-'{s,pendingEffect}';x:=jsonb_set(x,'{s,effectQueue}',jsonb_build_array(e)||(x#>'{s,effectQueue}'),true);return public._r_drain(x);
 end if;
 if pending is not null then raise exception 'Resolva a habilidade pendente.';end if;
 if coalesce((res->>'playedThisTurn')::boolean,false) or coalesce((res->>'passed')::boolean,false) or coalesce((res->>'skipNextTurn')::boolean,false) then raise exception 'Não é possível jogar neste turno.';end if;
 c:=public._r_card(cid);if c='{}'::jsonb or coalesce((c->>'specialOnly')::boolean,false) then raise exception 'Carta indisponível.';end if;
 select ordinality::integer-1 into idx from jsonb_array_elements_text(coalesce(res->'hand','[]'::jsonb)) with ordinality a(value,ordinality) where value=cid order by ordinality limit 1;if idx is null then raise exception 'Essa carta não está na sua mão.';end if;
 lane:=greatest(0,least(2,coalesce((a->>'lane')::integer,0)));
 if c->>'kind'='equipment' and not exists(select 1 from jsonb_array_elements(x#>array['s',t,'field']) u where public._r_equip(cid,u)) then raise exception 'Não há alvo compatível para o equipamento.';end if;
 x:=jsonb_set(x,array['r',actor,'hand'],(res->'hand')-idx,true);x:=public._r_spawn(x,cid,t,actor,lane);x:=jsonb_set(x,array['r',actor,'playedThisTurn'],'true'::jsonb,true);
 x:=jsonb_set(x,'{s,log}',jsonb_build_array(coalesce(c->>'name',cid)||' entrou em jogo.')||coalesce(x#>'{s,log}','[]'::jsonb),true);
 return public._r_drain(x);
end; $$;
create or replace function public._r_round_end(s jsonb) returns jsonb language plpgsql volatile set search_path='' as $$
declare x jsonb:=jsonb_build_object('s',s,'r','{}'::jsonb);t text;u jsonb;v jsonb;
begin
 if s->>'endEffectsRound'=s->>'round' then return s;end if;
 if public._r_live(s) then foreach t in array array['player_one','player_two'] loop for u in select value from jsonb_array_elements(s#>array[t,'field']) loop
  if public._r_id(u)='ra' then for v in select value from jsonb_array_elements(x#>array['s',t,'field']) where public._r_card(value->>'cardId')->>'faction'='Egípcios' loop x:=public._r_change(x,t,v->>'uid',t,1);end loop;end if;
  if public._r_id(u)='hercules' then v:=public._r_unit(x->'s',t,u->>'uid');v:=jsonb_set(v,'{progress}',to_jsonb(least(12,coalesce((v->>'progress')::integer,0)+1)),true);x:=public._r_set_unit(x,t,u->>'uid',v);end if;
 end loop;end loop;end if;return jsonb_set(x->'s','{endEffectsRound}',s->'round',true);
end; $$;
create or replace function public._r_clear_round(s jsonb) returns jsonb language plpgsql volatile set search_path='' as $$
declare x jsonb:=jsonb_build_object('s',s,'r','{}'::jsonb);t text; ids jsonb;
begin foreach t in array array['player_one','player_two'] loop select coalesce(jsonb_agg(value->'uid'),'[]'::jsonb) into ids from jsonb_array_elements(x#>array['s',t,'field']);x:=public._r_destroy(x,t,ids,false);x:=jsonb_set(x,array['s',t,'roundScoreBonus'],'0'::jsonb,true);end loop;return jsonb_set((x->'s')-'pendingEffect','{effectQueue}','[]'::jsonb,true);end; $$;

