     definition:=replace(definition,$h$for unit in select value from jsonb_array_elements(coalesce(one_state->'field','[]'::jsonb)) loop$h$,$h$s:=jsonb_set(s,'{player_one}',one_state,true);s:=jsonb_set(s,'{player_two}',two_state,true);s:=public._r_clear_round(s);one_state:=s->'player_one';two_state:=s->'player_two';for unit in select value from jsonb_array_elements(coalesce(one_state->'field','[]'::jsonb)) loop$h$);
    end if;
    definition:=replace(definition,anchor,anchor||replacement);
    foreach score_name in array array['one_score','two_score','one_total','two_total','score_one','score_two','total_one','total_two'] loop definition:=regexp_replace(definition,score_name||'[[:space:]]+integer',score_name||' numeric','g');end loop;
    definition:=replace(definition,$h$(s#>>'{totalPoints,player_one}')::integer$h$,$h$(s#>>'{totalPoints,player_one}')::numeric$h$);definition:=replace(definition,$h$(s#>>'{totalPoints,player_two}')::integer$h$,$h$(s#>>'{totalPoints,player_two}')::numeric$h$);
    if position('ability_result jsonb' in definition)=0 or position('public._r_round_end(s)' in definition)=0 or position('public._r_clear_round(s)' in definition)=0 then raise exception 'Unrecognized abilities integration in %; no changes applied.',routine.proname;end if;
   elsif routine.proname<>'submit_game_action' then raise exception 'Unrecognized play dispatch in %; no changes applied.',routine.proname;end if;
  end if;
  if definition<>original then execute definition;end if;
 end loop;
end; $migration$;

-- Only the player resolving the effect should receive the private reveal through the RPC.
do $privacy$
declare p record; definition text;
begin for p in select f.oid from pg_proc f join pg_namespace n on n.oid=f.pronamespace where n.nspname='public' and f.proname='get_online_match' loop
 definition:=pg_get_functiondef(p.oid);
 if position('/* abilities_reveal_privacy */' in definition)=0 then
  definition:=replace(definition,$h$if coalesce(g.team_size,1)=1 then$h$,$h$if coalesce(g.team_size,1)=1 then /* abilities_reveal_privacy */ enemy_key:=case when g.player_one=auth.uid() then 'player_two' else 'player_one' end;g.state:=jsonb_set(g.state,array[enemy_key],(g.state->enemy_key)-'privateEffects',true);$h$);
  execute definition;
 end if;end loop;
end; $privacy$;
do $permissions$
declare p record;
begin for p in select f.oid::regprocedure signature from pg_proc f join pg_namespace n on n.oid=f.pronamespace where n.nspname='public' and left(f.proname,3)='_r_' loop execute 'revoke all on function '||p.signature||' from public,anon,authenticated';end loop;end; $permissions$;
revoke all on function public._terrain_card_meta(text) from public,anon,authenticated;
commit;
